import { strFromU8, strToU8, unzipSync, zipSync, type Zippable } from 'fflate'

// pdf2docx writes Word files from python-docx's template, which brings its
// own details: the author "python-docx", the comment "generated by
// python-docx", dates from 2013, "Microsoft Macintosh Word" as the app, and
// a thumbnail picture that has nothing to do with the document. Tuls clears
// them, as it clears PDFs' details, and names itself as the app.

const CORE = 'docProps/core.xml'
const APP = 'docProps/app.xml'
const XML = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
const EMPTY_CORE = `${XML}<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:dcmitype="http://purl.org/dc/dcmitype/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"/>`
const TULS_APP = `${XML}<Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties" xmlns:vt="http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes"><Application>Tuls</Application></Properties>`
const THUMBNAIL =
  /<Relationship\b[^>]*\bType="[^"]*\/metadata\/thumbnail"[^>]*\/>/g

/** The Word file without its template's details. */
export function cleanDocx(docx: Uint8Array): Uint8Array<ArrayBuffer> {
  const files = unzipSync(docx)
  if (files[CORE]) files[CORE] = strToU8(EMPTY_CORE)
  if (files[APP]) files[APP] = strToU8(TULS_APP)
  const rels = files['_rels/.rels'] && strFromU8(files['_rels/.rels'])
  if (rels) {
    for (const link of rels.match(THUMBNAIL) ?? []) {
      const target = /\bTarget="\/?([^"]*)"/.exec(link)?.[1]
      if (target) {
        delete files[target]
        const types = files['[Content_Types].xml']
        if (types) {
          files['[Content_Types].xml'] = strToU8(
            strFromU8(types).replace(
              new RegExp(`<Override\\b[^>]*PartName="/${target}"[^>]*/>`),
              '',
            ),
          )
        }
      }
    }
    files['_rels/.rels'] = strToU8(rels.replace(THUMBNAIL, ''))
  }
  // Text parts are compressed; pictures and the like already are.
  const repacked: Zippable = {}
  for (const [name, data] of Object.entries(files)) {
    repacked[name] = [data, { level: /\.(xml|rels)$/i.test(name) ? 6 : 0 }]
  }
  return zipSync(repacked) as Uint8Array<ArrayBuffer>
}
